from fractions import Fraction

def cond_exp(probs, X, atoms):
    """E[X | G] outcome by outcome. atoms is a list of lists of outcome indices."""
    out = [None] * len(X)
    for a in atoms:
        pa = sum(probs[i] for i in a)
        m = sum(probs[i] * X[i] for i in a) / pa
        for i in a:
            out[i] = Fraction(m)
    return out

def mse(probs, X, Y):
    """E[(X - Y)^2] as a Fraction."""
    return sum(Fraction(p) * (x - y) ** 2 for p, x, y in zip(probs, X, Y))
